def maxPairStrength(nums):
    # Euclid's algorithm for the greatest common divisor
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    # Distinct values in descending order (equal values give strength 1 only)
    vals = sorted(set(nums), reverse=True)
    # Every pair has strength at least 1
    best = 1

    for i in range(len(vals)):
        # Even the best possible pairing for this i cannot beat best: stop
        if i + 1 < len(vals) and vals[i] * vals[i + 1] <= best:
            break
        for j in range(i + 1, len(vals)):
            # Strength is at most a * b, and later j are smaller, so stop
            if vals[i] * vals[j] <= best:
                break
            g = gcd(vals[i], vals[j])
            # (a * b) / g^2 = (a / g) * (b / g), computed exactly
            strength = (vals[i] // g) * (vals[j] // g)
            if strength > best:
                best = strength
    return best
